-- 4. Which part each spot of water belongs to: runs of 30 m grid cells along each grid row.
--    Grid: x = (lon - 125.7) * 110582.25626663613, y = (lat - 6.6) * 110574; ix = round(x/30), iy = round(y/30).
create table cots_private.area_cells (
  iy integer not null,
  ix_start integer not null,
  ix_end integer not null check (ix_end >= ix_start),
  area_id uuid not null references public.monitoring_areas(id),
  primary key (iy, ix_start)
);
revoke all on cots_private.area_cells from public, anon, authenticated;
create temporary table area_cell_codes (iy integer, ix_start integer, ix_end integer, code text);
select c.iy, c.ix_start, c.ix_end, a.id from area_cell_codes c
join public.monitoring_areas a on a.code = c.code and a.geography_version = 'cots-davao-gulf-v2';
drop table area_cell_codes;

-- 5. The part at a location: the part that contains it, or the nearest part within 15 m (GPS allowance).
create function cots_private.area_at(lat double precision, lon double precision, allowance_m double precision default 15)
returns uuid language sql stable security definer set search_path = '' as $$
  with p as (
    select (lon - 125.7) * 110582.25626663613 / 30.0 as gx, (lat - 6.6) * 110574.0 / 30.0 as gy
  ), q as (
    select p.gx, p.gy, round(p.gx)::integer as ix, round(p.gy)::integer as iy from p
  ), c as (
    select a.area_id, a.iy, greatest(a.ix_start, least(a.ix_end, q.ix)) as cx, q.gx, q.gy
    from q join cots_private.area_cells a
      on a.iy between q.iy - 1 and q.iy + 1 and a.ix_start <= q.ix + 1 and a.ix_end >= q.ix - 1
  )
  select area_id from c
  where 30.0 * sqrt(power(greatest(abs(gx - cx) - 0.5, 0), 2) + power(greatest(abs(gy - iy) - 0.5, 0), 2)) <= allowance_m
  order by 30.0 * sqrt(power(greatest(abs(gx - cx) - 0.5, 0), 2) + power(greatest(abs(gy - iy) - 0.5, 0), 2)), area_id
  limit 1
$$;
revoke all on function cots_private.area_at(double precision, double precision, double precision) from public, anon, authenticated;

-- Short code of a monitoring area (for example V3-12), for messages.
create function cots_private.area_short_code(aid uuid) returns text
language sql stable security definer set search_path = '' as $$
  select coalesce(a.code, 'another area') from public.monitoring_areas a where a.id = aid
$$;
revoke all on function cots_private.area_short_code(uuid) from public, anon, authenticated;

-- 6. Location checks (new map only; old and test areas are not checked).
--    A record's GPS must be inside its part or within 15 m of it. Records without GPS are not checked here.
create function cots_private.check_capture_area() returns trigger
language plpgsql security definer set search_path = '' as $$
declare a public.monitoring_areas; found uuid;
begin
  select * into a from public.monitoring_areas where id = new.area_id;
  if not a.active then
    raise exception 'COTS_AREA_INACTIVE: This monitoring area is no longer used. Please update the app.' using errcode = '23514';
  end if;
  if a.geography_version = 'cots-davao-gulf-v2' and new.latitude is not null then
    found := cots_private.area_at(new.latitude::double precision, new.longitude::double precision);
    if found is null then
      raise exception 'COTS_AREA_OUTSIDE: This photo''s location is outside every monitoring area (on land or in deep water).' using errcode = '23514';
    elsif found <> new.area_id then
      raise exception 'COTS_AREA_MISMATCH:%: This photo was taken in %, not %.', cots_private.area_short_code(found),
        cots_private.area_short_code(found), a.code using errcode = '23514';
    end if;
  end if;
  return new;
end $$;
create trigger check_capture_area before insert on public.captures
  for each row execute function cots_private.check_capture_area();

create function cots_private.check_survey_area() returns trigger
language plpgsql security definer set search_path = '' as $$
declare a public.monitoring_areas; found uuid;
begin
  select ma.* into a from public.follow_up_assignments f join public.monitoring_areas ma on ma.id = f.area_id
  where f.id = new.assignment_id;
  if a.geography_version = 'cots-davao-gulf-v2' and new.latitude is not null then
    found := cots_private.area_at(new.latitude::double precision, new.longitude::double precision);
    if found is null then
      raise exception 'COTS_AREA_OUTSIDE: This visit''s location is outside every monitoring area (on land or in deep water).' using errcode = '23514';
    elsif found <> a.id then
      raise exception 'COTS_AREA_MISMATCH:%: This visit was recorded in %, not %.', cots_private.area_short_code(found),
        cots_private.area_short_code(found), a.code using errcode = '23514';
    end if;
  end if;
  return new;
end $$;
create trigger check_survey_area before insert on public.follow_up_surveys
  for each row execute function cots_private.check_survey_area();

-- A visit's photos must be in the visit's part.
create function cots_private.check_survey_capture_area() returns trigger
language plpgsql security definer set search_path = '' as $$
declare visit_area uuid; photo_area uuid; v text;
begin
  select f.area_id into visit_area from public.follow_up_surveys s
    join public.follow_up_assignments f on f.id = s.assignment_id where s.id = new.survey_id;
  select c.area_id into photo_area from public.captures c where c.id = new.capture_id;
  select ma.geography_version into v from public.monitoring_areas ma where ma.id = visit_area;
  if v = 'cots-davao-gulf-v2' and photo_area is distinct from visit_area then
    raise exception 'COTS_AREA_MISMATCH:%: Some photos were taken in %, not %. Please submit them as a separate visit for %.',
      cots_private.area_short_code(photo_area), cots_private.area_short_code(photo_area), cots_private.area_short_code(visit_area),
      cots_private.area_short_code(photo_area) using errcode = '23514';
  end if;
  return new;
end $$;
create trigger check_survey_capture_area before insert on public.survey_captures
  for each row execute function cots_private.check_survey_capture_area();

revoke all on function cots_private.check_capture_area() from public, anon, authenticated;
revoke all on function cots_private.check_survey_area() from public, anon, authenticated;
revoke all on function cots_private.check_survey_capture_area() from public, anon, authenticated;
